import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.qCVWde4n.js";const g=JSON.parse('{"title":"Chat apps","description":"","frontmatter":{},"headers":[],"relativePath":"channels.md","filePath":"channels.md"}'),n={name:"channels.md"};function i(r,e,h,l,d,c){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="chat-apps" tabindex="-1">Chat apps <a class="header-anchor" href="#chat-apps" aria-label="Permalink to &quot;Chat apps&quot;">​</a></h1><p>Your nanoMuse inside the chat apps you already use: Feishu (飞书 / Lark), DingTalk (钉钉), WeCom (企业微信) and Telegram. Write to the bot from your phone and the same Muse answers — one conversation per chat, the reply typed out as it comes, tool work shown as a status line, approvals answered with a word or a button. Chats you mark <em>deliver here</em> also get what the Muse does on its own: check-ins, reminders, the result of a background task, the question it needs you to answer.</p><p>Nothing needs a public address. Each vendor offers a long connection the bot opens from inside your network (Telegram: long polling), so the runtime behind your router or on a laptop is enough. The vendors&#39; own SDKs do the socket work; they are optional extras:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;nanomuse[feishu]&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # lark-oapi</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;nanomuse[dingtalk]&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # dingtalk-stream</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;nanomuse[wecom]&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # wecom-aibot-sdk-python</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;nanomuse[channels]&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # all three; Telegram needs nothing extra</span></span></code></pre></div><p>The Docker image carries all of them. Without an SDK the app shows the line to install and leaves the switch alone.</p><h2 id="where-to-find-it" tabindex="-1">Where to find it <a class="header-anchor" href="#where-to-find-it" aria-label="Permalink to &quot;Where to find it&quot;">​</a></h2><ul><li><p><strong>App</strong> — Settings → <em>Chat apps</em> (「聊天入口」). One card per app: the switch, the credentials, who may talk to it, the paired chats and their <em>deliver here</em> switch, a <em>Send a test message</em> button and the setup steps with a link to the vendor console.</p></li><li><p><strong>Terminal</strong> — <code>nanomuse channels status | pending | approve &lt;code&gt; | deny &lt;code&gt; | login feishu [--lark] | test &lt;name&gt;</code>. With <code>nanomuse serve</code> running the commands go through its API; otherwise they edit the files under <code>&lt;data_dir&gt;/channels/</code> and the server picks them up when it starts (or on <em>Reload</em>).</p></li><li><p><strong>API</strong> — <code>GET /api/channels</code>, <code>PUT /api/channels/&lt;name&gt;</code>, <code>POST /api/channels/pairing/&lt;code&gt;/approve|deny</code>, <code>PUT|DELETE /api/channels/&lt;name&gt;/chats/&lt;sender&gt;</code>, <code>POST /api/channels/&lt;name&gt;/test</code>, <code>POST /api/channels/deliver {text}</code>, <code>POST /api/channels/reload</code>, and for Feishu <code>POST /api/channels/feishu/login</code> + <code>GET /api/channels/feishu/login/&lt;device_code&gt;</code>.</p></li><li><p><strong>config.toml</strong> — a <code>[channels.&lt;name&gt;]</code> table works too, for a server set up by hand:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">channels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">telegram</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bot_token = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${TELEGRAM_BOT_TOKEN}&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">allow_from = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;123456789&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Telegram user ids that never need a code</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">group_policy = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mention&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # or &quot;open&quot;</span></span></code></pre></div><p>What the app saves wins per field. Secrets set in the app go to the vault (<code>{{vault:CHANNEL_TELEGRAM_BOT_TOKEN}}</code> stays in the file) and are never shown again — a secret field only says whether something is set.</p></li></ul><h2 id="setting-up-each-app" tabindex="-1">Setting up each app <a class="header-anchor" href="#setting-up-each-app" aria-label="Permalink to &quot;Setting up each app&quot;">​</a></h2><p>The console names below are as of 2026; vendors move things around.</p><h3 id="feishu-lark" tabindex="-1">Feishu / Lark <a class="header-anchor" href="#feishu-lark" aria-label="Permalink to &quot;Feishu / Lark&quot;">​</a></h3><p>The short way: in the app press <strong>Create the bot by QR code</strong> (or run <code>nanomuse channels login feishu</code>, <code>--lark</code> for the international edition), scan with Feishu, confirm, done — the App ID and Secret are saved and the channel switches on. This is Feishu&#39;s own scan-to-create flow for personal agents; it makes an app with the bot capability and the long-connection events already set.</p><p>By hand, at <a href="https://open.feishu.cn/app" target="_blank" rel="noreferrer">https://open.feishu.cn/app</a> (Lark: <a href="https://open.larksuite.com/app" target="_blank" rel="noreferrer">https://open.larksuite.com/app</a>):</p><ol><li><em>Create custom app</em> → <em>Add capability</em> → <strong>Bot</strong>.</li><li><em>Permissions</em>: <code>im:message</code>, <code>im:message.p2p_msg:readonly</code>, <code>im:message.group_at_msg:readonly</code>, <code>im:resource</code> (images and files).</li><li><em>Events &amp; callbacks</em>: subscription mode <strong>Long connection</strong>, add <code>im.message.receive_v1</code>; callback mode <strong>Long connection</strong>, add <code>card.action.trigger</code> (the approval buttons).</li><li><em>Credentials &amp; Basic Info</em>: copy <strong>App ID</strong> and <strong>App Secret</strong> into the app; pick <em>feishu</em> or <em>lark</em>. Leave <em>Encrypt Key</em> and <em>Verification Token</em> empty unless you set them in the console.</li><li><em>Version management</em> → create a version → publish.</li></ol><p>Replies are interactive cards with a markdown body; while a reply streams the card is patched in place (about once a second). A 👍 on your message means the Muse is working on it. In groups the bot answers when it is @-mentioned.</p><h3 id="dingtalk" tabindex="-1">DingTalk <a class="header-anchor" href="#dingtalk" aria-label="Permalink to &quot;DingTalk&quot;">​</a></h3><p>At <a href="https://open-dev.dingtalk.com/" target="_blank" rel="noreferrer">https://open-dev.dingtalk.com/</a>:</p><ol><li><em>Create app</em> (企业内部应用) → <em>Add capability</em> → <strong>Robot</strong> (机器人).</li><li>Message receive mode: <strong>Stream</strong> (Stream 模式). No callback URL.</li><li><em>Credentials &amp; Basic Info</em> (凭证与基础信息): copy <strong>Client ID</strong> (AppKey) and <strong>Client Secret</strong> (AppSecret).</li><li><em>Permissions</em>: the robot&#39;s send-message scope (<code>qyapi_robot_sendmsg</code>) so a <em>deliver here</em> chat can be written to without a message to reply to.</li><li>Publish the version; add the robot to a group or find it in the address book.</li></ol><p>DingTalk messages cannot be edited, so a reply arrives once, when it is complete. A robot in a DingTalk group only hears messages that @ it.</p><h3 id="wecom" tabindex="-1">WeCom <a class="header-anchor" href="#wecom" aria-label="Permalink to &quot;WeCom&quot;">​</a></h3><p>In the WeCom admin console (企业微信管理后台) → <em>Security &amp; management</em> → <strong>Intelligent robot</strong> (智能机器人):</p><ol><li><em>Create robot</em> → <strong>API mode</strong> (API 模式), connection <strong>long connection</strong> (长连接).</li><li>Copy the <strong>Bot ID</strong> and <strong>Secret</strong> into the app.</li><li>Add the robot to the chats where it should listen, or let people find it in the address book.</li></ol><p>The socket host (<code>openws.work.weixin.qq.com</code>) is added to <code>NO_PROXY</code> for the runtime process; a corporate HTTPS proxy usually cannot carry it. Replies stream over the same socket; proactive messages (delivery) are markdown.</p><h3 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram&quot;">​</a></h3><ol><li>In Telegram talk to <strong>@BotFather</strong>, send <code>/newbot</code>, copy the token into the app.</li><li>Direct messages work at once. For a group, add the bot to it; with BotFather&#39;s <em>Group Privacy</em> on (the default) it only hears @-mentions and replies to its own messages, which matches the <em>mention</em> policy.</li><li>If <code>api.telegram.org</code> is out of reach from the computer, set <strong>Proxy</strong> (<code>socks5://…</code> or <code>http://…</code>).</li></ol><p>Replies are sent and then edited in place while they stream (Telegram&#39;s 4096-character limit splits long ones). Approvals are two inline buttons.</p><h2 id="pairing-who-may-talk-to-the-bot" tabindex="-1">Pairing: who may talk to the bot <a class="header-anchor" href="#pairing-who-may-talk-to-the-bot" aria-label="Permalink to &quot;Pairing: who may talk to the bot&quot;">​</a></h2><p>Anyone who finds the bot can write to it; the Muse answers only people you let in.</p><ul><li>The first direct message from an unknown person gets a <strong>pairing code</strong> (six letters and digits, no 0/O/1/I, good for ten minutes) and nothing else — the message does not reach the Muse. Approve the code under Settings → Chat apps, or <code>nanomuse channels approve &lt;code&gt;</code>. The person is told, and from then on their messages go through.</li><li><strong>Always allowed</strong> (<code>allow_from</code>): vendor user ids that never need a code. A lone <code>*</code> lets everyone in — only for a bot nobody else can reach.</li><li><strong>Groups</strong>: unknown people in a group are ignored quietly (no codes in groups). An approved person&#39;s group message is answered when the bot is @-mentioned (<code>group_policy = &quot;mention&quot;</code>), or on every message (<code>&quot;open&quot;</code>). The group is its own conversation; the sender&#39;s name travels with each line.</li><li><strong>Remove</strong> a paired chat in the app (or delete it from <code>pairing.json</code>); the next message gets a new code.</li></ul><p>Pairings and codes live in <code>&lt;data_dir&gt;/channels/pairing.json</code> — the data directory, not the workspace, so the agent&#39;s own file tools cannot change who may talk to it.</p><h2 id="how-a-chat-maps-to-the-muse" tabindex="-1">How a chat maps to the Muse <a class="header-anchor" href="#how-a-chat-maps-to-the-muse" aria-label="Permalink to &quot;How a chat maps to the Muse&quot;">​</a></h2><p>Each chat is one conversation of the agent, with the id <code>channel-&lt;app&gt;-&lt;chat id&gt;</code> and the title <em>Feishu · Ann</em> / <em>Telegram · Team</em> in the app&#39;s drawer. A message from the chat goes through the same entry point as a message typed in the app, so everything else — memory, goals, the Sentinel, skills — is the same Muse. Attachments (photos, files, voice notes) are saved under the workspace&#39;s <code>attachments/</code> and attached to the message.</p><p>While the run works:</p><ul><li>text streams into the reply as the model writes (where the vendor allows edits);</li><li>a running tool shows as a short italic line in the same message (&quot;Searching the web&quot;, 正在运行命令) until text replaces it;</li><li>an <strong>approval</strong> the Sentinel asks for arrives in the chat: a card with 允许 / 拒绝 buttons on Feishu and Telegram, a message asking for the word on DingTalk and WeCom. <code>allow</code>, <code>yes</code>, <code>ok</code>, <code>允许</code>, <code>同意</code> approve once; <code>deny</code>, <code>no</code>, <code>拒绝</code>, <code>不行</code> refuse. The decision is the same as pressing the card in the app;</li><li>files the run produced (an artifact event) are sent when the run ends;</li><li>a <strong>question</strong> the Muse asks is delivered, and your next line answers it.</li></ul><p>Language follows <code>agent.language</code>: <code>zh</code> for Chinese lines, <code>en</code> for English, <code>auto</code> for both.</p><h2 id="deliver-here" tabindex="-1">Deliver here <a class="header-anchor" href="#deliver-here" aria-label="Permalink to &quot;Deliver here&quot;">​</a></h2><p>Switch <em>Deliver here</em> on for a paired chat and it also receives what the Muse does without being asked — the same events the phone app turns into notifications: a background run&#39;s final words (quiet ones excepted), an approval that is waiting (answer it from the chat), a question that needs you. One Muse may deliver to several chats; each decides for itself. <code>POST /api/channels/deliver {&quot;text&quot;: …}</code> sends a line to all of them — useful from a script or a reminder.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><ul><li>Secrets go to the vault and never come back out of the API; the settings file holds placeholders. Logs carry the vendor&#39;s error text, not credentials.</li><li>Only paired or allow-listed people reach the Muse; unknown people get a code, or silence in a group. A button press on an approval card is honoured only from a paired person.</li><li>An approval from a chat is a <em>once</em> decision with the reason &quot;from Feishu&quot; (etc.) — nothing is remembered from a chat.</li><li>The channel data lives in the data directory, outside the agent&#39;s reach.</li><li>The connections are outbound only; no port is opened and no public URL is involved.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Not installed</strong></td><td>the SDK is missing on the machine running nanoMuse: run the line shown (<code>pip install &#39;nanomuse[feishu]&#39;</code>), then switch the channel on again</td></tr><tr><td><strong>Needs settings</strong></td><td>a required field is empty; the card names it</td></tr><tr><td><strong>Error</strong> with the vendor&#39;s words</td><td>the credentials were refused or the vendor is unreachable; fix and switch off/on, or <em>Save</em> again</td></tr><tr><td>the bot does not answer in a group</td><td>the group policy is <em>mention</em> and the bot was not @-mentioned; or the sender is not paired (groups never show codes)</td></tr><tr><td>Feishu replies but no reaction / no card buttons</td><td>missing <code>im:message.group_at_msg:readonly</code> / <code>im:resource</code>, or <code>card.action.trigger</code> is not on the long connection</td></tr><tr><td>Feishu: &quot;app secret invalid&quot;</td><td>the App Secret was regenerated in the console; paste the new one</td></tr><tr><td>DingTalk connects but gets nothing</td><td>the robot&#39;s receive mode is not <em>Stream</em>, or the version was not published</td></tr><tr><td>WeCom: connection errors behind a proxy</td><td>the socket bypasses <code>HTTPS_PROXY</code>; the host must be reachable directly</td></tr><tr><td>Telegram: <code>Conflict: terminated by other getUpdates request</code></td><td>the same token is polled from two places (another runtime, or a webhook); use one</td></tr><tr><td>codes keep coming back</td><td>approve one within ten minutes; <code>nanomuse channels pending</code> lists them</td></tr><tr><td><code>nanomuse channels …</code> says the server refused the token</td><td><code>server.token</code> in config.toml differs from the running server&#39;s; or run it with the same <code>--config</code></td></tr></tbody></table><p><code>nanomuse channels status --json</code> prints the same view the app gets.</p>`,41)])])}const m=t(n,[["render",i]]);export{g as __pageData,m as default};
